solution:
public static long MinimumNetwork(int count, int[][] edges)
{
    if (count == 0) return 0; var used = new bool[count]; var best = Enumerable.Repeat(long.MaxValue, count).ToArray(); best[0] = 0; long total = 0; for (int step = 0; step < count; step++) { int v = -1; for (int i = 0; i < count; i++) if (!used[i] && (v == -1 || best[i] < best[v])) v = i; if (best[v] == long.MaxValue) return -1; used[v] = true; total += best[v]; foreach (var edge in edges) { int u = edge[0] == v ? edge[1] : edge[1] == v ? edge[0] : -1; if (u >= 0 && !used[u]) best[u] = Math.Min(best[u], (long)edge[2]); } } return total;
}

