solution:
public static int RegionSize(int[][] grid, int row, int column)
{
    if (grid.Length == 0 || grid[0].Length == 0 || grid[row][column] == 0) return 0; int rows = grid.Length, cols = grid[0].Length; var seen = new bool[rows,cols]; var queue = new Queue<(int r,int c)>(); queue.Enqueue((row,column)); seen[row,column] = true; int count = 0; int[] dr = [-1,1,0,0], dc = [0,0,-1,1]; while (queue.Count > 0) { var p = queue.Dequeue(); count++; for (int d = 0; d < 4; d++) { int r = p.r+dr[d], c = p.c+dc[d]; if (r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] == 1 && !seen[r,c]) { seen[r,c] = true; queue.Enqueue((r,c)); } } } return count;
}

