solution:
public static long EvaluateRpn(string[] tokens)
{
    var stack = new Stack<long>(); foreach (string token in tokens) { if (token != "+" && token != "-" && token != "*" && token != "/") { stack.Push(long.Parse(token, System.Globalization.CultureInfo.InvariantCulture)); continue; } long right = stack.Pop(), left = stack.Pop(); stack.Push(token switch { "+" => left+right, "-" => left-right, "*" => left*right, _ => left/right }); } return stack.Pop();
}

