solution:
public static string NormalizeUnixPath(string path)
{
    var parts = new List<string>(); foreach (string part in path.Split('/')) { if (part == "" || part == ".") continue; if (part == "..") { if (parts.Count > 0) parts.RemoveAt(parts.Count-1); } else parts.Add(part); } return "/" + string.Join("/", parts);
}

