public static string CanonicalQuery(string[][] pairs)
{
    return string.Join("&", pairs.OrderBy(p => p[0], StringComparer.Ordinal).ThenBy(p => p[1], StringComparer.Ordinal).Select(p => Uri.EscapeDataString(p[0]) + "=" + Uri.EscapeDataString(p[1])));
}

