    throw new NotImplementedException();
}

solution:
public static int[] CountRanges(int[] sorted, int[][] ranges)
{
    var output = new int[ranges.Length]; for (int q = 0; q < ranges.Length; q++) { int lo = 0, hi = sorted.Length; while (lo < hi) { int mid = lo+(hi-lo)/2; if (sorted[mid] < ranges[q][0]) lo = mid+1; else hi = mid; } int start = lo; lo = 0; hi = sorted.Length; while (lo < hi) { int mid = lo+(hi-lo)/2; if (sorted[mid] <= ranges[q][1]) lo = mid+1; else hi = mid; } output[q] = lo-start; } return output;
}

