public static int NearestWarehouse(int[][] sites, int x, int y)
{
    if (sites.Length == 0) return -1; return sites.OrderBy(s => Math.Abs((long)s[1]-x) + Math.Abs((long)s[2]-y)).ThenBy(s => s[0]).First()[0];
}

