public static int[] AllocateUnits(int[] weights, int units)
{
    long total = weights.Sum(w => (long)w); var result = new int[weights.Length]; if (total == 0) return result; long assigned = 0; for (int i = 0; i < weights.Length; i++) { result[i] = (int)((long)weights[i]*units/total); assigned += result[i]; } var order = Enumerable.Range(0,weights.Length).OrderByDescending(i => (long)weights[i]*units%total).ThenBy(i => i).ToArray(); for (int i = 0; i < units-assigned; i++) result[order[i]]++; return result;
}

