solution:
public static long[] ApplyPayment(int[] invoices, long payment)
{
    var remaining = invoices.Select(x => (long)x).ToArray(); for (int i = 0; i < remaining.Length && payment > 0; i++) { long used = Math.Min(remaining[i],payment); remaining[i] -= used; payment -= used; } return remaining;
}

