public static int[] AcceptedEvents(int[][] events, int ttl)
{
    var last = new Dictionary<int,int>(); var accepted = new List<int>(); for (int i = 0; i < events.Length; i++) { int id = events[i][0], time = events[i][1]; if (!last.TryGetValue(id,out int previous) || (long)time-previous >= ttl) { accepted.Add(i); last[id] = time; } } return accepted.ToArray();
}

