solution:
public static long ParseIpv4(string address)
{
    string[] parts = address.Split('.'); if (parts.Length != 4) return -1; long result = 0; for (int i = 0; i < 4; i++) { string p = parts[i]; if (p.Length == 0 || p.Length > 3 || p.Length > 1 && p[0] == '0' || p.Any(c => c < '0' || c > '9')) return -1; int octet = int.Parse(p, System.Globalization.CultureInfo.InvariantCulture); if (octet > 255) return -1; result = result*256 + octet; } return result;
}
